function pollAdminDetails(a){if(currentUser().admin!==true)return'';const votes=Object.entries(a.oylar||{});if(!votes.length)return'<div class="ka-muted">Henüz oy kullanan yok.</div>';return `<details><summary class="ka-btn ka-btn--ghost ka-btn--sm">Kim neye oy verdi?</summary><div class="ka-stack" style="padding-top:8px">${votes.map(([vuid,v])=>{const labels=(v?.secenekIdler||[]).map(id=>a.secenekler?.find(x=>x.id===id)?.metin||'?').join(', ');return `<div class="ka-row ka-row--between"><strong>${esc(v?.ad||vuid)}</strong><span class="ka-muted">${esc(labels)}</span></div>`}).join('')}</div></details>`}
